import numpy as np
from scipy.optimize import newton

# Define the polynomial P(x) = x^3 + 3x^2 - 1
def P(x):
    return x**3 + 3*x**2 - 1

# Find approximate roots using numerical methods
# We expect roots near -3, 0, and 1/3
roots = []
for guess in [-3, 0, 0.3]:
    try:
        root = newton(P, guess)
        if abs(root**3 + 3*root**2 - 1) < 1e-9:
            roots.append(root)
    except RuntimeError:
        pass

# Check the condition derived: Q(x) = 15x^2 + 2x - 5
def Q(x):
    return 15*x**2 + 2*x - 5

print("Roots of x^3 + 3x^2 - 1 = 0 found:")
for r in roots:
    print(f"Root x = {r:.5f}")
    print(f"Check Q(x) = 15x^2 + 2x - 5: {Q(r):.5f}")
